        al.qr = True
    if al.ihead:
        al.ihead = [x.lower() for x in al.ihead]
    if HAVE_SSL:
        if al.ssl_ver:
            configure_ssl_ver(al)
        if al.ciphers:
            configure_ssl_ciphers(al)
    else:
        warn("ssl module does not exist; cannot enable https")
        al.http_only = True
    if PY2 and WINDOWS and al.e2d:
        warn(
