def _handle_changed_object(sender, instance, raw=False, **kwargs):
    """
    Fires when an object is created or updated.
    """
    if raw:
        return
    if change_context_state.get() is None:
        return
    if kwargs.get("created"):
        action = ObjectChangeActionChoices.ACTION_CREATE
    elif "created" in kwargs:
        action = ObjectChangeActionChoices.ACTION_UPDATE
    elif kwargs.get("action") in ["post_add", "post_remove"] and kwargs["pk_set"]:
        action = ObjectChangeActionChoices.ACTION_UPDATE
    else:
        return
    if hasattr(instance, "to_objectchange"):
        user = _get_user_if_authenticated(change_context_state.get().get_user(), instance)
        original_cache = instance._state.fields_cache.copy()
        related_changes = ObjectChange.objects.filter(
            changed_object_type=ContentType.objects.get_for_model(instance),
            changed_object_id=instance.pk,
            user=user,
            request_id=change_context_state.get().change_id,
        )
        objectchange = instance.to_objectchange(action)
        if related_changes.exists():
            most_recent_change = related_changes.order_by("-time").first()
            if most_recent_change.action == ObjectChangeActionChoices.ACTION_DELETE:
                most_recent_change.action = ObjectChangeActionChoices.ACTION_UPDATE
            most_recent_change.object_data = objectchange.object_data
            most_recent_change.object_data_v2 = objectchange.object_data_v2
            most_recent_change.save()
            objectchange = most_recent_change
        else:
            objectchange.user = user
            objectchange.request_id = change_context_state.get().change_id
            objectchange.change_context = change_context_state.get().context
            objectchange.change_context_detail = change_context_state.get().context_detail[
                :CHANGELOG_MAX_CHANGE_CONTEXT_DETAIL
            ]
            objectchange.save()
        instance._state.fields_cache = original_cache
    if action == ObjectChangeActionChoices.ACTION_CREATE:
        model_inserts.labels(instance._meta.model_name).inc()
    elif action == ObjectChangeActionChoices.ACTION_UPDATE:
        model_updates.labels(instance._meta.model_name).inc()
    changelog_retention = get_settings_or_config("CHANGELOG_RETENTION")
    if changelog_retention and random.randint(1, 1000) == 1:
        cutoff = timezone.now() - timedelta(days=changelog_retention)
        ObjectChange.objects.filter(time__lt=cutoff).delete()
def custom_links(context, obj):
    """
    Render all applicable links for the given object.
    """
    content_type = ContentType.objects.get_for_model(obj)
    links = CustomLink.objects.filter(content_type=content_type)
    if not links:
        return ""
    link_context = {
        "obj": obj,
        "debug": context.get("debug", False),
        "request": context["request"],
        "user": context["user"],
        "perms": context["perms"],
    }
    template_code = mark_safe("")
    group_names = OrderedDict()
    for cl in links:
        if cl.group_name and cl.group_name in group_names:
            group_names[cl.group_name].append(cl)
        elif cl.group_name:
            group_names[cl.group_name] = [cl]
        else:
            try:
                text_rendered = render_jinja2(cl.text, link_context)
                if text_rendered:
                    link_rendered = render_jinja2(cl.target_url, link_context)
                    link_target = ' target="_blank"' if cl.new_window else ""
                    template_code += format_html(
                        LINK_BUTTON, link_rendered, link_target, cl.button_class, text_rendered
                    )
            except Exception as e:
                template_code += format_html(
                    '<a class="btn btn-sm btn-default" disabled="disabled" title="{}">'
                    '<i class="mdi mdi-alert"></i> {}</a>\n',
                    e,
                    cl.name,
                )
    for group, links in group_names.items():
        links_rendered = mark_safe("")
        for cl in links:
            try:
                text_rendered = render_jinja2(cl.text, link_context)
                if text_rendered:
                    link_target = ' target="_blank"' if cl.new_window else ""
                    link_rendered = render_jinja2(cl.target_url, link_context)
                    links_rendered += format_html(GROUP_LINK, link_rendered, link_target, text_rendered)
            except Exception as e:
                links_rendered += format_html(
                    '<li><a disabled="disabled" title="{}"><span class="text-muted">'
                    '<i class="mdi mdi-alert"></i> {}</span></a></li>',
                    e,
                    cl.name,
                )
        if links_rendered:
            template_code += format_html(GROUP_BUTTON, links[0].button_class, group, links_rendered)
    return template_code

class WMABaseView(TemplateView):
    model_admin = None
    meta_title = ""
    page_title = ""
    page_subtitle = ""
    def __init__(self, model_admin):
        self.model_admin = model_admin
        self.model = model_admin.model
        self.opts = self.model._meta
        self.app_label = force_str(self.opts.app_label)
        self.model_name = force_str(self.opts.model_name)
        self.verbose_name = force_str(self.opts.verbose_name)
        self.verbose_name_plural = force_str(self.opts.verbose_name_plural)
        self.pk_attname = self.opts.pk.attname
        self.is_pagemodel = model_admin.is_pagemodel
        self.permission_helper = model_admin.permission_helper
        self.url_helper = model_admin.url_helper
    def check_action_permitted(self, user):
        return True
    def dispatch(self, request, *args, **kwargs):
        if not self.check_action_permitted(request.user):
            raise PermissionDenied
        button_helper_class = self.model_admin.get_button_helper_class()
        self.button_helper = button_helper_class(self, request)
        return super().dispatch(request, *args, **kwargs)
    def menu_icon(self):
        return self.model_admin.get_menu_icon()
    def header_icon(self):
        return self.menu_icon
    def get_page_title(self):
        return self.page_title or capfirst(self.opts.verbose_name_plural)
    def get_meta_title(self):
        return self.meta_title or self.get_page_title()
    def index_url(self):
        return self.url_helper.index_url
    def create_url(self):
        return self.url_helper.create_url
    def get_base_queryset(self, request=None):
        return self.model_admin.get_queryset(request or self.request)
    def get_context_data(self, **kwargs):
        context = {
            "view": self,
            "model_admin": self.model_admin,
        }
        context.update(kwargs)
        return super().get_context_data(**context)
