def set_page_position(request, page_to_move_id):
    page_to_move = get_object_or_404(Page, id=page_to_move_id)
    parent_page = page_to_move.get_parent()
    if not parent_page.permissions_for_user(request.user).can_reorder_children():
        raise PermissionDenied
    if request.method == "POST":
        position = request.GET.get("position", None)
        position_page = None
        if position is not None:
            try:
                position_page = parent_page.get_children()[int(position)]
            except IndexError:
                pass
        if position_page:
            old_position = list(parent_page.get_children()).index(page_to_move)
            if int(position) < old_position:
                page_to_move.move(position_page, pos="left", user=request.user)
            elif int(position) > old_position:
                page_to_move.move(position_page, pos="right", user=request.user)
        else:
            page_to_move.move(parent_page, pos="last-child", user=request.user)
    return HttpResponse("")
    def add_redirect(
        old_path,
        redirect_to=None,
        is_permanent=True,
        page_route_path=None,
        site=None,
        automatically_created=False,
    ):
        """
        Create and save a Redirect instance with a single method.
        :param old_path: the path you wish to redirect
        :param site: the Site (instance) the redirect is applicable to (if not all sites)
        :param redirect_to: a Page (instance) or path (string) where the redirect should point
        :param is_permanent: whether the redirect should be indicated as permanent (i.e. 301 redirect)
        :return: Redirect instance
        """
        redirect = Redirect()
        redirect.old_path = Redirect.normalise_path(old_path)
        redirect.site = site
        if isinstance(redirect_to, Page):
            redirect.redirect_page = redirect_to
            if isinstance(page_route_path, str):
                redirect.redirect_page_route_path = Redirect.normalise_page_route_path(
                    page_route_path
                )
        elif isinstance(redirect_to, str):
            redirect.redirect_link = redirect_to
        redirect.is_permanent = is_permanent
        redirect.automatically_created = automatically_created
        redirect.save()
        return redirect

def origin_from_url(url: str) -> str:
    parts = urlparse(url)
    new = [parts[0], parts[1], "", "", "", ""]
    return urlunparse(new)
def allow_redirect_url(url: str) -> bool:
    """
    Check that a redirect target is allowed against the CORS policy.
    The "Cross-Origin Resource Sharing" configuration specifies which external hosts
    are allowed to access Open Forms. We leverage this configuration to block or allow
    redirects to external hosts.
    """
    cors = CorsMiddleware()
    origin = origin_from_url(url)
    parts = urlparse(url)
    if not cors_conf.CORS_ALLOW_ALL_ORIGINS and not cors.origin_found_in_white_lists(
        origin, parts
    ):
        return False
    else:
        return True

