    return recipe_json, recipe_tree, html_data, images
    def __init__(self, request, cache_mode, ignore_automations=False):
        """
        Initialize ingredient parser
        :param request: request context (to control caching, rule ownership, etc.)
        :param cache_mode: defines if all rules should be loaded on initialization (good when parser is used many times) or if they should be retrieved every time (good when parser is not used many times in a row)
        :param ignore_automations: ignore automation rules, allows to use ingredient parser without database access/request (request can be None)
        """
        self.request = request
        self.ignore_rules = ignore_automations
        if cache_mode:
            FOOD_CACHE_KEY = f'automation_food_alias_{self.request.space.pk}'
            if c := caches['default'].get(FOOD_CACHE_KEY, None):
                self.food_aliases = c
                caches['default'].touch(FOOD_CACHE_KEY, 30)
            else:
                for a in Automation.objects.filter(space=self.request.space, disabled=False, type=Automation.FOOD_ALIAS).only('param_1', 'param_2').all():
                    self.food_aliases[a.param_1] = a.param_2
                caches['default'].set(FOOD_CACHE_KEY, self.food_aliases, 30)
            UNIT_CACHE_KEY = f'automation_unit_alias_{self.request.space.pk}'
            if c := caches['default'].get(UNIT_CACHE_KEY, None):
                self.unit_aliases = c
                caches['default'].touch(UNIT_CACHE_KEY, 30)
            else:
                for a in Automation.objects.filter(space=self.request.space, disabled=False, type=Automation.UNIT_ALIAS).only('param_1', 'param_2').all():
                    self.unit_aliases[a.param_1] = a.param_2
                caches['default'].set(UNIT_CACHE_KEY, self.unit_aliases, 30)
        else:
            self.food_aliases = {}
            self.unit_aliases = {}

class Olm:
    def _olm_encrypt(self, session, recipient_device, message_type, content):
        payload = {
            "sender": self.user_id,
            "sender_device": self.device_id,
            "keys": {"ed25519": self.account.identity_keys["ed25519"]},
            "recipient": recipient_device.user_id,
            "recipient_keys": {
                "ed25519": recipient_device.ed25519,
            },
            "type": message_type,
            "content": content,
        }
        olm_message = session.encrypt(Api.to_json(payload))
        self.store.save_session(recipient_device.curve25519, session)
        return {
            "algorithm": self._olm_algorithm,
            "sender_key": self.account.identity_keys["curve25519"],
            "ciphertext": {
                recipient_device.curve25519: {
                    "type": olm_message.message_type,
                    "body": olm_message.ciphertext,
                }
            },
        }
    def handle_to_device_event(self, event):
        """Consume to-device events decrypting them if necessary.
        Args:
            event (ToDeviceEvent): The to-device event that should be handled.
        Returns a new event if the event was encrypted and successfully
        decrypted, otherwise None.
        """
        decrypted_event = None
        if isinstance(event, EncryptedToDeviceEvent):
            decrypted_event = self.decrypt_event(event)
        elif isinstance(event, KeyVerificationEvent):
            self.handle_key_verification(event)
        elif isinstance(event, (RoomKeyRequest, RoomKeyRequestCancellation)):
            self._handle_key_requests(event)
        return decrypted_event
    def _handle_key_requests(self, event):
        if isinstance(event, RoomKeyRequest):
            if event.algorithm == Olm._megolm_algorithm:
                self.received_key_requests[event.request_id] = event
            else:
                logger.warn(
                    f"Received key request from {event.sender} via {event.requesting_device_id} "
                    f"with an unknown algorithm: {event.algorithm}"
                )
        elif isinstance(event, RoomKeyRequestCancellation):
            self.received_key_requests.pop(event.request_id, None)
            user_key = (event.sender, event.requesting_device_id)
            self.key_requests_waiting_for_session[user_key].pop(event.request_id, None)
            if not self.key_requests_waiting_for_session[user_key]:
                try:
                    device = self.device_store[event.sender][event.requesting_device_id]
                    self.key_request_devices_no_session.remove(device)
                except (KeyError, ValueError):
                    pass
            if event.request_id in self.key_request_from_untrusted:
                self.key_request_from_untrusted.pop(event.request_id)
                self.received_key_requests[event.request_id] = event
    def share_with_ourselves(self, event):
        """Share a room key with some other device owned by our own user.
        Args:
            event (RoomKeyRequest): The event of the key request.
        If the key share request is valid this will queue up a to-device
        message that holds the room key.
        Raises EncryptionError if no Olm session was found to encrypt
        the key. Raises OlmTrustError if the device that requested the key is
        not verified. Raises a KeyShareError if the request is invalid and
        can't be handled.
        """
        logger.debug(
            f"Trying to share key {event.session_id} with {event.sender}:{event.requesting_device_id}"
        )
        group_session = self.inbound_group_store.get(
            event.room_id, event.sender_key, event.session_id
        )
        if not group_session:
            raise KeyShareError(
                f"Failed to re-share key {event.session_id} with {event.sender}: No session found"
            )
        try:
            device = self.device_store[event.sender][event.requesting_device_id]
        except KeyError:
            raise KeyShareError(
                f"Failed to re-share key {event.session_id} with {event.sender}: "
                f"Unknown requesting device {event.requesting_device_id}."
            )
        session = self.session_store.get(device.curve25519)
        if not session:
            if device not in self.key_request_devices_no_session:
                self.key_request_devices_no_session.append(device)
            self.key_requests_waiting_for_session[(device.user_id, device.device_id)][
                event.request_id
            ] = event
            raise EncryptionError(
                f"No Olm session found for {device.user_id} and device {device.id}"
            )
        if not device.verified:
            raise OlmUnverifiedDeviceError(
                device,
                f"Failed to re-share key {event.session_id} with {event.sender}: "
                f"Device {event.requesting_device_id} is not verified",
            )
        logger.debug(
            f"Successfully shared a key {event.session_id} with {event.sender}:{event.requesting_device_id}"
        )
        self.outgoing_to_device_messages.append(
            self._encrypt_forwarding_key(event.room_id, group_session, session, device)
        )
    def get_active_key_requests(self, user_id, device_id):
        """Get key requests from a device that are waiting for verification.
        Args:
            user_id (str): The id of the user for which we would like to find
                the active key requests.
            device_id (str): The id of the device for which we would like to
                find the active key requests.
        """
        return [
            event
            for event in self.key_request_from_untrusted.values()
            if event.sender == user_id and event.requesting_device_id == device_id
        ]
    def continue_key_share(self, event):
        """Continue a previously interrupted key share event.
        Args:
            event (RoomKeyRequest): The event which we would like to continue.
        """
        if event not in self.key_request_from_untrusted.values():
            raise LocalProtocolError("No such pending key share request found")
        event = self.key_request_from_untrusted[event.request_id]
        if not self._collect_single_key_share(event):
            return False
        self.key_request_from_untrusted.pop(event.request_id)
        return True
    def cancel_key_share(self, event):
        """Cancel a previously interrupted key share event.
        Args:
            event (RoomKeyRequest): The event which we would like to cancel.
        """
        return bool(self.key_request_from_untrusted.pop(event.request_id, None))
    def _collect_single_key_share(self, event):
        if event.sender == self.user_id:
            try:
                self.share_with_ourselves(event)
            except KeyShareError as error:
                logger.warn(error)
            except EncryptionError as error:
                logger.warn(error)
            except OlmTrustError:
                return False
        return True
    def collect_key_requests(self):
        """Turn queued up key requests into to-device messages for key sharing.
        Returns RoomKeyRequest events that couldn't be sent out because the
        requesting device isn't verified or ignored.
        """
        events_for_users = []
        for event in self.received_key_requests.values():
            if isinstance(event, RoomKeyRequestCancellation):
                events_for_users.append(event)
                continue
            if not self._collect_single_key_share(event):
                self.key_request_from_untrusted[event.request_id] = event
                events_for_users.append(event)
        self.received_key_requests = dict()
        return events_for_users
    def _handle_key_claiming(self, response):
        keys = response.one_time_keys
        for user_id, user_devices in keys.items():
            for device_id, one_time_key in user_devices.items():
                try:
                    device = self.device_store[user_id][device_id]
                except KeyError:
                    logger.warn(
                        f"Curve key for user {user_id} and device {device_id} not found, failed to start Olm session"
                    )
                    continue
                logger.info(
                    f"Found curve key for user {user_id} and device {device_id}"
                )
                key_object = next(iter(one_time_key.values()))
                verified = self.verify_json(
                    key_object, device.ed25519, user_id, device_id
                )
                if verified:
                    logger.info(
                        f"Successfully verified signature for one-time key of device {device_id} of user {user_id}."
                    )
                    logger.info(
                        f"Creating Outbound Session for device {device_id} of user {user_id}"
                    )
                    session = self.create_session(key_object["key"], device.curve25519)
                    if device in self.wedged_devices:
                        self.wedged_devices.remove(device)
                        self._queue_dummy_message(session, device)
                    if device in self.key_request_devices_no_session:
                        self.key_request_devices_no_session.remove(device)
                        events = self.key_requests_waiting_for_session.pop(
                            (device.user_id, device.device_id), {}
                        )
                        self.received_key_requests.update(events)
                else:
                    logger.warn(
                        "Signature verification for one-time key of "
                        f"device {device_id} of user {user_id} failed, could not start "
                        "Olm session."
                    )
    def _mark_to_device_message_as_sent(self, message):
        """Mark a to-device message as sent.
        This removes the to-device message from our outgoing to-device list.
        """
        try:
            self.outgoing_to_device_messages.remove(message)
            if isinstance(message, DummyMessage):
                events = self.key_re_requests_events.pop(
                    (message.recipient, message.recipient_device), []
                )
                requested_sessions = []
                for event in events:
                    if event.session_id in requested_sessions:
                        continue
                    message = event.as_key_request(
                        event.sender, self.device_id, event.session_id, event.device_id
                    )
                    logger.info(
                        f"Queuing a room key re-request for a unwedged "
                        f"Olm session: {event.sender} {event.sender} "
                        f"{event.session_id}."
                    )
                    self.outgoing_to_device_messages.append(message)
                    requested_sessions.append(event.session_id)
            elif isinstance(message, RoomKeyRequestMessage):
                key_request = OutgoingKeyRequest.from_message(message)
                self.outgoing_key_requests[message.request_id] = key_request
                self.store.add_outgoing_key_request(key_request)
        except ValueError:
            pass
    def handle_response(self, response):
        if isinstance(response, KeysUploadResponse):
            self.account.shared = True
            self.uploaded_key_count = response.signed_curve25519_count
            self.mark_keys_as_published()
            self.save_account()
        elif isinstance(response, KeysQueryResponse):
            self._handle_key_query(response)
        elif isinstance(response, KeysClaimResponse):
            self._handle_key_claiming(response)
        elif isinstance(response, RoomKeyRequestResponse):
            key_request = OutgoingKeyRequest.from_response(response)
            self.outgoing_key_requests[response.request_id] = key_request
            self.store.add_outgoing_key_request(key_request)
        elif isinstance(response, ToDeviceResponse):
            self._mark_to_device_message_as_sent(response.to_device_message)
    def get_users_for_key_claiming(self):
        """Get the content for a key claim request that needs to be made.
        Returns a dictionary containing users as the keys and a list of devices
        for which we will claim one-time keys.
        Raises a LocalProtocolError if no key claim request needs to be made.
        """
        if not self.wedged_devices and not self.key_request_devices_no_session:
            raise LocalProtocolError("No wedged sessions found.")
        wedged = defaultdict(list)
        for device in self.wedged_devices:
            wedged[device.user_id].append(device.device_id)
        for device in self.key_request_devices_no_session:
            if device in wedged[device.user_id]:
                continue
            wedged[device.user_id].append(device.device_id)
        return wedged
    def _handle_forwarded_room_key_event(
        self,
        sender,
        sender_key,
        payload,
    ):
        event = ForwardedRoomKeyEvent.from_dict(payload, sender, sender_key)
        if isinstance(event, (BadEvent, UnknownBadEvent)):
            return event
        if event.algorithm != "m.megolm.v1.aes-sha2":
            logger.error(
                f"Error: unsupported forwarded room key of type {event.algorithm}"
            )
            return None
        if event.session_id not in self.outgoing_key_requests:
            logger.info(
                "Ignoring session key we have not requested from device {}.", sender_key
            )
            return None
        key_request = self.outgoing_key_requests[event.session_id]
        if (
            event.algorithm != key_request.algorithm
            or event.room_id != key_request.room_id
            or event.session_id != key_request.session_id
        ):
            logger.info(
                "Ignoring session key with mismatched algorithm, room_id, or "
                "session id."
            )
            return None
        content = payload["content"]
        session_sender_key = content["sender_key"]
        signing_key = content["sender_claimed_ed25519_key"]
        chain = content["forwarding_curve25519_key_chain"]
        chain.append(session_sender_key)
        session = Olm._import_group_session(
            content["session_key"],
            signing_key,
            session_sender_key,
            event.room_id,
            chain,
        )
        if not session:
            return None
        if self.inbound_group_store.add(session):
            self.save_inbound_group_session(session)
        key_request = self.outgoing_key_requests.pop(key_request.request_id)
        self.store.remove_outgoing_key_request(key_request)
        self.outgoing_to_device_messages.append(
            key_request.as_cancellation(self.user_id, self.device_id)
        )
        return event
    def check_if_wedged(self, event: MegolmEvent):
        """Check if a Megolm event failed decryption because they keys got lost
        because of a wedged Olm session.
        """
        try:
            device = self.device_store[event.sender][event.device_id]
        except KeyError:
            logger.warn(
                f"Received a undecryptable Megolm event from a unknown "
                f"device: {event.sender} {event.device_id}"
            )
            self.users_for_key_query.add(event.sender)
            return
        session = self.session_store.get(device.curve25519)
        if not session:
            logger.warn(
                f"Received a undecryptable Megolm event from a device "
                f"with no Olm sessions: {event.sender} {event.device_id}"
            )
            return
        session_age = datetime.now() - session.creation_time
        if (
            session_age < self._unwedging_interval
            and event.session_id not in self.outgoing_key_requests
        ):
            logger.info(
                f"Received a undecryptable Megolm event from a device "
                f"that we recently established an Olm session with: "
                f"{event.sender} {event.device_id}."
            )
            message = event.as_key_request(
                event.sender, self.device_id, event.session_id, event.device_id
            )
            self.outgoing_to_device_messages.append(message)
        if device in self.wedged_devices:
            logger.info(
                f"Received a undecryptable Megolm event from a device "
                f"that has a wedged Olm session: "
                f"{event.sender} {event.device_id}."
            )
            self.key_re_requests_events[(device.user_id, device.device_id)].append(
                event
            )
    def decrypt_event(
        self,
        event,
        room_id=None,
    ):
        logger.debug(f"Decrypting event of type {type(event).__name__}")
        if isinstance(event, OlmEvent):
            try:
                own_key = self.account.identity_keys["curve25519"]
                own_ciphertext = event.ciphertext[own_key]
            except KeyError:
                logger.warn("Olm event doesn't contain ciphertext for our key")
                return None
            if own_ciphertext["type"] == 0:
                message = OlmPreKeyMessage(own_ciphertext["body"])
            elif own_ciphertext["type"] == 1:
                message = OlmMessage(own_ciphertext["body"])
            else:
                logger.warn(f"Unsupported olm message type: {own_ciphertext['type']}")
                return None
            return self.decrypt(event.sender, event.sender_key, message)
        elif isinstance(event, MegolmEvent):
            try:
                return self.decrypt_megolm_event(event, room_id)
            except EncryptionError:
                return None
        return None
    def share_group_session_parallel(
        self, room_id: str, users: List[str], ignore_unverified_devices: bool = False
    ) -> Iterator[Tuple[Set[Tuple[str, str]], Dict[str, Any]]]:
        logger.info(f"Sharing group session for room {room_id}")
        if room_id not in self.outbound_group_sessions:
            self.create_outbound_group_session(room_id)
        group_session = self.outbound_group_sessions[room_id]
        if group_session.shared:
            self.create_outbound_group_session(room_id)
            group_session = self.outbound_group_sessions[room_id]
        key_content = {
            "algorithm": self._megolm_algorithm,
            "room_id": room_id,
            "session_id": group_session.id,
            "session_key": group_session.session_key,
        }
        already_shared_set = group_session.users_shared_with
        ignored_set = group_session.users_ignored
        user_map = []
        mark_as_ignored = []
        for user_id in users:
            for device in self.device_store.active_user_devices(user_id):
                if device.id == self.device_id:
                    ignored_set.add((user_id, device.id))
                    continue
                if self.is_device_blacklisted(device):
                    ignored_set.add((user_id, device.id))
                    continue
                if (user_id, device.id) in already_shared_set or (
                    user_id,
                    device.id,
                ) in ignored_set:
                    continue
                session = self.session_store.get(device.curve25519)
                if not session:
                    logger.warn(
                        f"Missing Olm session for user {user_id} and device "
                        f"{device.id}, skipping"
                    )
                    continue
                if not self.is_device_verified(device):
                    if self.is_device_ignored(device):
                        pass
                    elif ignore_unverified_devices:
                        mark_as_ignored.append(device)
                    else:
                        raise OlmUnverifiedDeviceError(
                            device,
                            f"Device {device.id} for user {device.user_id} is not "
                            f"verified or blacklisted.",
                        )
                user_map.append((user_id, device, session))
        if mark_as_ignored:
            self.store.ignore_devices(mark_as_ignored)
        for user_map_chunk in chunks(user_map, self._maxToDeviceMessagesPerRequest):
            to_device_dict = {"messages": {}}
            sharing_with = set()
            for user_id, device, session in user_map_chunk:
                olm_dict = self._olm_encrypt(session, device, "m.room_key", key_content)
                sharing_with.add((user_id, device.id))
                if user_id not in to_device_dict["messages"]:
                    to_device_dict["messages"][user_id] = {}
                to_device_dict["messages"][user_id][device.id] = olm_dict
            yield (sharing_with, to_device_dict)
    def load(self):
        self.session_store = self.store.load_sessions()
        self.inbound_group_store = self.store.load_inbound_group_sessions()
        self.device_store = self.store.load_device_keys()
        self.outgoing_key_requests = self.store.load_outgoing_key_requests()
    async def send(
        self,
        method: str,
        path: str,
        data: Union[None, str, AsyncDataT] = None,
        headers: Optional[Dict[str, str]] = None,
        trace_context: Any = None,
        timeout: Optional[float] = None,
    ) -> ClientResponse:
        """Send a request to the homeserver.
        This function does not call receive_response().
        Args:
            method (str): The request method that should be used. One of get,
                post, put, delete.
            path (str): The URL path of the request.
            data (str, optional): Data that will be posted with the request.
            headers (Dict[str,str] , optional): Additional request headers that
                should be used with the request.
            trace_context (Any, optional): An object to use for the
                ClientSession TraceConfig context
            timeout (int, optional): How many seconds the request has before
                raising `asyncio.TimeoutError`.
                Overrides `AsyncClient.config.request_timeout` if not `None`.
        """
        assert self.client_session
        return await self.client_session.request(
            method,
            self.homeserver + path,
            data=data,
            ssl=self.ssl,
            headers=headers,
            trace_request_ctx=trace_context,
            timeout=self.config.request_timeout if timeout is None else timeout,
        )
    async def share_group_session(
        self,
        room_id: str,
        ignore_unverified_devices: bool = False,
    ) -> Union[ShareGroupSessionResponse, ShareGroupSessionError]:
        """Share a group session with a room.
        This method sends a group session to members of a room.
        Automatically called by room_send().
        Calls receive_response() to update the client state if necessary.
        Args:
            room_id(str): The room id of the room where the message should be
                sent to.
            ignore_unverified_devices(bool): Mark unverified devices as
                ignored. Ignored devices will still receive encryption
                keys for messages but they won't be marked as verified.
        Raises LocalProtocolError if the client isn't logged in, if the session
        store isn't loaded, no room with the given room id exists, the room
        isn't an encrypted room or a key sharing request is already in flight
        for this room.
        """
        assert self.olm
        try:
            room = self.rooms[room_id]
        except KeyError:
            raise LocalProtocolError(f"No such room with id {room_id}")
        if not room.encrypted:
            raise LocalProtocolError(f"Room with id {room_id} is not encrypted")
        if room_id in self.sharing_session:
            raise LocalProtocolError(f"Already sharing a group session for {room_id}")
        self.sharing_session[room_id] = AsyncioEvent()
        missing_sessions = self.get_missing_sessions(room_id)
        if missing_sessions:
            await self.keys_claim(missing_sessions)
        shared_with = set()
        try:
            requests = []
            for sharing_with, to_device_dict in self.olm.share_group_session_parallel(
                room_id,
                list(room.users.keys()),
                ignore_unverified_devices=ignore_unverified_devices,
            ):
                method, path, data = Api.to_device(
                    self.access_token, "m.room.encrypted", to_device_dict, uuid4()
                )
                requests.append(
                    self._send(
                        ShareGroupSessionResponse,
                        method,
                        path,
                        data,
                        response_data=(room_id, sharing_with),
                    )
                )
            for response in await asyncio.gather(*requests, return_exceptions=True):
                if isinstance(response, ShareGroupSessionResponse):
                    shared_with.update(response.users_shared_with)
            self.olm.outbound_group_sessions[room_id].shared = True
        except ClientConnectionError:
            raise
        finally:
            event = self.sharing_session.pop(room_id)
            event.set()
        return ShareGroupSessionResponse(room_id, shared_with)
    async def request_room_key(
        self,
        event: MegolmEvent,
        tx_id: Optional[str] = None,
    ) -> Union[RoomKeyRequestResponse, RoomKeyRequestError]:
        """Request a missing room key.
        This sends out a message to other devices requesting a room key from
        them.
        Calls receive_response() to update the client state if necessary.
        Returns either a `RoomKeyRequestResponse` if the request was successful
        or a `RoomKeyRequestError` if there was an error with the request.
        Raises a LocalProtocolError if the room key was already requested.
        Args:
            event (MegolmEvent): An undecrypted MegolmEvent for which we would
                like to request the decryption key.
        """
        uuid = tx_id or uuid4()
        if event.session_id in self.outgoing_key_requests:
            raise LocalProtocolError(
                "A key sharing request is already sent" " out for this session id."
            )
        assert self.user_id
        assert self.device_id
        message = event.as_key_request(self.user_id, self.device_id)
        method, path, data = Api.to_device(
            self.access_token, message.type, message.as_dict(), uuid
        )
        return await self._send(
            RoomKeyRequestResponse,
            method,
            path,
            data,
            (
                event.session_id,
                event.session_id,
                event.room_id,
                event.algorithm,
            ),
        )
    async def export_keys(self, outfile: str, passphrase: str, count: int = 10000):
        """Export all the Megolm decryption keys of this device.
        The keys will be encrypted using the passphrase.
        Note that this does not save other information such as the private
        identity keys of the device.
        Args:
            outfile (str): The file to write the keys to.
            passphrase (str): The encryption passphrase.
            count (int): Optional. Round count for the underlying key
                derivation. It is not recommended to specify it unless
                absolutely sure of the consequences.
        """
        assert self.store
        assert self.olm
        loop = asyncio.get_event_loop()
        inbound_group_store = self.store.load_inbound_group_sessions()
        export_keys = partial(
            self.olm.export_keys_static,
            inbound_group_store,
            outfile,
            passphrase,
            count,
        )
        await loop.run_in_executor(None, export_keys)
    async def import_keys(self, infile: str, passphrase: str):
        """Import Megolm decryption keys.
        The keys will be added to the current instance as well as written to
        database.
        Args:
            infile (str): The file containing the keys.
            passphrase (str): The decryption passphrase.
        Raises `EncryptionError` if the file is invalid or couldn't be
            decrypted.
        Raises the usual file errors if the file couldn't be opened.
        """
        assert self.store
        assert self.olm
        loop = asyncio.get_event_loop()
        import_keys = partial(self.olm.import_keys_static, infile, passphrase)
        sessions = await loop.run_in_executor(None, import_keys)
        for session in sessions:
            if self.olm.inbound_group_store.add(session):
                self.store.save_inbound_group_session(session)
    def _check_commitment(self, key: str):
        assert self.commitment
        calculated_commitment = olm.sha256(
            key + Api.to_canonical_json(self.start_verification().content)
        )
        return self.commitment == calculated_commitment
    def _send(
        self,
        request,
        request_info,
        uuid=None,
    ):
        assert self.connection
        ret_uuid, data = self.connection.send(request, uuid)
        self.requests_made[ret_uuid] = request_info
        return ret_uuid, data
    def _build_request(self, api_response, timeout=0):
        def unpack_api_call(method, *rest):
            return method, rest
        method, api_data = unpack_api_call(*api_response)
        if isinstance(self.connection, HttpConnection):
            if method == "GET":
                path = self._add_extra_path(api_data[0])
                return HttpRequest.get(self.host, path, timeout)
            elif method == "POST":
                path, data = api_data
                path = self._add_extra_path(path)
                return HttpRequest.post(self.host, path, data, timeout)
            elif method == "PUT":
                path, data = api_data
                path = self._add_extra_path(path)
                return HttpRequest.put(self.host, path, data, timeout)
        elif isinstance(self.connection, Http2Connection):
            if method == "GET":
                path = api_data[0]
                path = self._add_extra_path(path)
                return Http2Request.get(self.host, path, timeout)
            elif method == "POST":
                path, data = api_data
                path = self._add_extra_path(path)
                return Http2Request.post(self.host, path, data, timeout)
            elif method == "PUT":
                path, data = api_data
                path = self._add_extra_path(path)
                return Http2Request.put(self.host, path, data, timeout)
        assert "Invalid connection type"
    def share_group_session(
        self,
        room_id,
        ignore_missing_sessions=False,
        tx_id=None,
        ignore_unverified_devices=False,
    ):
        """Share a group session with a room.
        This method sends a group session to members of a room.
        Args:
            room_id(str): The room id of the room where the message should be
                sent to.
            tx_id(str, optional): The transaction ID of this event used to
                uniquely identify this message.
            ignore_unverified_devices(bool): Mark unverified devices as
                ignored. Ignored devices will still receive encryption
                keys for messages but they won't be marked as verified.
        Raises LocalProtocolError if the client isn't logged in, if the session
        store isn't loaded, no room with the given room id exists or the room
        isn't an encrypted room.
        """
        assert self.olm
        try:
            room = self.rooms[room_id]
        except KeyError:
            raise LocalProtocolError(f"No such room with id {room_id}")
        if not room.encrypted:
            raise LocalProtocolError(f"Room with id {room_id} is not encrypted")
        user_map, to_device_dict = self.olm.share_group_session(
            room_id,
            list(room.users.keys()),
            ignore_missing_sessions,
            ignore_unverified_devices,
        )
        uuid = tx_id or uuid4()
        request = self._build_request(
            Api.to_device(self.access_token, "m.room.encrypted", to_device_dict, uuid)
        )
        return self._send(
            request, RequestInfo(ShareGroupSessionResponse, (room_id, user_map))
        )
    def request_room_key(self, event, tx_id=None):
        """Request a missing room key.
        This sends out a message to other devices requesting a room key from
        them.
        Returns a unique uuid that identifies the request and the bytes that
        should be sent to the socket.
        Args:
            event (str): An undecrypted MegolmEvent for which we would like to
                request the decryption key.
        """
        uuid = tx_id or uuid4()
        if event.session_id in self.outgoing_key_requests:
            raise LocalProtocolError(
                "A key sharing request is already sent" " out for this session id."
            )
        assert self.user_id
        assert self.device_id
        message = event.as_key_request(self.user_id, self.device_id)
        request = self._build_request(
            Api.to_device(self.access_token, message.type, message.as_dict(), uuid)
        )
        return self._send(
            request,
            RequestInfo(
                RoomKeyRequestResponse,
                (event.session_id, event.session_id, event.room_id, event.algorithm),
            ),
        )
    def _create_response(self, request_info, transport_response, max_events=0):
        request_class = request_info.request_class
        extra_data = request_info.extra_data or ()
        try:
            content_type = str(transport_response.headers[b"content-type"], "utf-8")
        except KeyError:
            content_type = None
        try:
            disposition = str(
                transport_response.headers[b"content-disposition"], "utf-8"
            )
            filename = cgi.parse_header(disposition)[1]["filename"]
        except KeyError:
            filename = None
        is_json = content_type == "application/json"
        if issubclass(request_class, FileResponse) and is_json:
            parsed_dict = self.parse_body(transport_response)
            response = request_class.from_data(
                parsed_dict, content_type, filename, *extra_data
            )
        elif issubclass(request_class, FileResponse):
            body = transport_response.content
            response = request_class.from_data(
                body, content_type, filename, *extra_data
            )
        else:
            parsed_dict = self.parse_body(transport_response)
            if (
                transport_response.status_code == 401
                and request_class == DeleteDevicesResponse
            ):
                response = DeleteDevicesAuthResponse.from_dict(parsed_dict)
            response = request_class.from_dict(parsed_dict, *extra_data)
        assert response
        logger.info(f"Received new response of type {response.__class__.__name__}")
        response.start_time = transport_response.send_time
        response.end_time = transport_response.receive_time
        response.timeout = transport_response.timeout
        response.status_code = transport_response.status_code
        response.uuid = transport_response.uuid
        return response
    def receive(self, data):
        """Pass received data to the client"""
        assert self.connection
        try:
            response = self.connection.receive(data)
        except (h11.RemoteProtocolError, h2.exceptions.ProtocolError) as e:
            raise RemoteTransportError(e)
        if response:
            try:
                request_info = self.requests_made.pop(response.uuid)
            except KeyError:
                logger.error(f"{pprint.pformat(self.requests_made)}")
                raise
            if response.is_ok:
                logger.info(f"Received response of type: {request_info.request_class}")
            else:
                logger.info(
                    ("Error with response of type type: {}, " "error code {}").format(
                        request_info.request_class, response.status_code
                    )
                )
            self.parse_queue.append((request_info, response))
        return
    def olm_account_shared(self) -> bool:
        """Check if the clients Olm account is shared with the server.
        Returns True if the Olm account is shared, False otherwise.
        """
        assert self.olm
        return self.olm.account.shared
    def invalidate_outbound_session(self, room_id: str):
        """Explicitly remove encryption keys for a room.
        Args:
            room_id (str): Room id for the room the encryption keys should be
                removed.
        """
        assert self.olm
        session = self.olm.outbound_group_sessions.pop(room_id, None)
        if session and not session.shared:
            self.olm.outbound_group_sessions[room_id] = session
        elif session:
            logger.info(f"Invalidating session for {room_id}")
    def _invalidate_outbound_sessions(self, device):
        assert self.olm
        for room in self.rooms.values():
            if device.user_id in room.users:
                self.invalidate_outbound_session(room.room_id)
    def verify_device(self, device: OlmDevice) -> bool:
        """Mark a device as verified.
        A device needs to be either trusted/ignored or blacklisted to either
        share room encryption keys with it or not.
        This method adds the device to the trusted devices and enables sharing
        room encryption keys with it.
        Args:
            device (OlmDevice): The device which should be added to the trust
                list.
        Returns true if the device was verified, false if it was already
        verified.
        """
        assert self.olm
        changed = self.olm.verify_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def unverify_device(self, device: OlmDevice) -> bool:
        """Unmark a device as verified.
        This method removes the device from the trusted devices and disables
        sharing room encryption keys with it. It also invalidates any
        encryption keys for rooms that the device takes part of.
        Args:
            device (OlmDevice): The device which should be added to the trust
                list.
        Returns true if the device was unverified, false if it was already
        unverified.
        """
        assert self.olm
        changed = self.olm.unverify_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def blacklist_device(self, device: OlmDevice) -> bool:
        """Mark a device as blacklisted.
        Devices on the blacklist will not receive room encryption keys and
        therefore won't be able to decrypt messages coming from this client.
        Args:
            device (OlmDevice): The device which should be added to the
                blacklist.
        Returns true if the device was added, false if it was on the blacklist
        already.
        """
        assert self.olm
        changed = self.olm.blacklist_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def unblacklist_device(self, device: OlmDevice) -> bool:
        """Unmark a device as blacklisted.
        Args:
            device (OlmDevice): The device which should be removed from the
                blacklist.
        Returns true if the device was removed, false if it wasn't on the
        blacklist and no removal happened.
        """
        assert self.olm
        changed = self.olm.unblacklist_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def ignore_device(self, device: OlmDevice) -> bool:
        """Mark a device as ignored.
        Ignored devices will still receive room encryption keys, despire not
        being verified.
        Args:
            device (OlmDevice): the device to ignore
        Returns true if device is ignored, or false if it is already on the
        list of ignored devices.
        """
        assert self.olm
        changed = self.olm.ignore_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def unignore_device(self, device: OlmDevice) -> bool:
        """Unmark a device as ignored.
        Args:
            device (OlmDevice): The device which should be removed from the
                list of ignored devices.
        Returns true if the device was removed, false if it wasn't on the
        list and no removal happened.
        """
        assert self.olm
        changed = self.olm.unignore_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def receive_response(
        self, response: Response
    ) -> Union[None, Coroutine[Any, Any, None]]:
        """Receive a Matrix Response and change the client state accordingly.
        Some responses will get edited for the callers convenience e.g. sync
        responses that contain encrypted messages. The encrypted messages will
        be replaced by decrypted ones if decryption is possible.
        Args:
            response (Response): the response that we wish the client to handle
        """
        if not isinstance(response, Response):
            raise ValueError("Invalid response received")
        if isinstance(response, LoginResponse):
            self._handle_login(response)
        elif isinstance(response, LogoutResponse):
            self._handle_logout(response)
        elif isinstance(response, RegisterResponse):
            self._handle_register(response)
        elif isinstance(response, SyncResponse):
            self._handle_sync(response)
        elif isinstance(response, RoomMessagesResponse):
            self._handle_messages_response(response)
        elif isinstance(response, RoomContextResponse):
            self._handle_context_response(response)
        elif isinstance(response, KeysUploadResponse):
            self._handle_olm_response(response)
        elif isinstance(response, KeysQueryResponse):
            self._handle_olm_response(response)
        elif isinstance(response, KeysClaimResponse):
            self._handle_olm_response(response)
        elif isinstance(response, ShareGroupSessionResponse):
            self._handle_olm_response(response)
        elif isinstance(response, JoinedMembersResponse):
            self._handle_joined_members(response)
        elif isinstance(response, RoomKeyRequestResponse):
            self._handle_olm_response(response)
        elif isinstance(response, RoomForgetResponse):
            self._handle_room_forget_response(response)
        elif isinstance(response, ToDeviceResponse):
            self._handle_olm_response(response)
        elif isinstance(response, RoomGetEventResponse):
            if isinstance(response.event, MegolmEvent) and self.olm is not None:
                try:
                    response.event = self.decrypt_event(response.event)
                except EncryptionError:
                    pass
        elif isinstance(response, PresenceGetResponse):
            self._handle_presence_response(response)
        elif isinstance(response, ErrorResponse):
            if response.soft_logout:
                self.access_token = ""
        return None
    def get_users_for_key_claiming(self) -> Dict[str, List[str]]:
        """Get the content for a key claim request that needs to be made.
        Returns a dictionary containing users as the keys and a list of devices
        for which we will claim one-time keys.
        Raises a LocalProtocolError if no key claim request needs to be made.
        """
        assert self.olm
        return self.olm.get_users_for_key_claiming()
    def get_active_key_requests(
        self, user_id: str, device_id: str
    ) -> List[RoomKeyRequest]:
        """Get key requests from a device that are waiting for verification.
        Args:
            user_id (str): The id of the user for which we would like to find
                the active key requests.
            device_id (str): The id of the device for which we would like to
                find the active key requests.
        Example:
            >>>
            >>>
            >>>
            >>>
            >>>   def key_share_cb(event):
            ...       user_id = event.sender
            ...       device_id = event.requesting_device_id
            ...       device = client.device_store[user_id][device_id]
            ...       client.verify_device(device)
            ...       for request in client.get_active_key_requests(
            ...           user_id, device_id):
            ...           client.continue_key_share(request)
            >>>   client.add_to_device_callback(key_share_cb)
        Returns:
            list: A list of actively waiting key requests from the given user.
        """
        assert self.olm
        return self.olm.get_active_key_requests(user_id, device_id)
    def continue_key_share(self, event: RoomKeyRequest) -> bool:
        """Continue a previously interrupted key share event.
        To handle room key requests properly client users need to add a
        callback for RoomKeyRequest:
            >>> client.add_to_device_callback(callback, RoomKeyRequest)
        This callback will be run only if a room key request needs user
        interaction, that is if a room key request is coming from an untrusted
        device.
        After a user has verified the requesting device the key sharing can be
        continued using this method:
            >>> client.continue_key_share(room_key_request)
        Args:
            event (RoomKeyRequest): The event which we would like to continue.
        If the key share event is continued successfully a to-device message
        will be queued up in the `client.outgoing_to_device_messages` list
        waiting to be sent out
        Returns:
            bool: True if the request was continued, False otherwise.
        """
        assert self.olm
        return self.olm.continue_key_share(event)
    def cancel_key_share(self, event: RoomKeyRequest) -> bool:
        """Cancel a previously interrupted key share event.
        This method is the counterpart to the `continue_key_share()` method. If
        a user choses not to verify a device and does not want to share room
        keys with such a device it should cancel the request with this method.
            >>> client.cancel_key_share(room_key_request)
        Args:
            event (RoomKeyRequest): The event which we would like to cancel.
        Returns:
            bool: True if the request was cancelled, False otherwise.
        """
        assert self.olm
        return self.olm.cancel_key_share(event)
    def send(self, request, uuid=None):
        data = b""
        if not isinstance(request, HttpRequest):
            raise TypeError("Invalid request type for HttpConnection")
        if self._connection.our_state == h11.IDLE and not self._current_response:
            data = data + self._connection.send(request._request)
            if request._data:
                data = data + self._connection.send(request._data)
            data = data + self._connection.send(request._end_of_message)
            if request.response:
                self._current_response = request.response
            else:
                self._current_response = HttpResponse(uuid, request.timeout)
            assert self._current_response
            self._current_response.mark_as_sent()
            return self._current_response.uuid, data
        else:
            request.response = HttpResponse(uuid, request.timeout)
            self._message_queue.append(request)
            return request.response.uuid, b""

class Olm:
    def _olm_encrypt(self, session, recipient_device, message_type, content):
        payload = {
            "sender": self.user_id,
            "sender_device": self.device_id,
            "keys": {"ed25519": self.account.identity_keys["ed25519"]},
            "recipient": recipient_device.user_id,
            "recipient_keys": {
                "ed25519": recipient_device.ed25519,
            },
            "type": message_type,
            "content": content,
        }
        olm_message = session.encrypt(Api.to_json(payload))
        self.store.save_session(recipient_device.curve25519, session)
        return {
            "algorithm": self._olm_algorithm,
            "sender_key": self.account.identity_keys["curve25519"],
            "ciphertext": {
                recipient_device.curve25519: {
                    "type": olm_message.message_type,
                    "body": olm_message.ciphertext,
                }
            },
        }
    def handle_to_device_event(self, event):
        """Consume to-device events decrypting them if necessary.
        Args:
            event (ToDeviceEvent): The to-device event that should be handled.
        Returns a new event if the event was encrypted and successfully
        decrypted, otherwise None.
        """
        decrypted_event = None
        if isinstance(event, EncryptedToDeviceEvent):
            decrypted_event = self.decrypt_event(event)
        elif isinstance(event, KeyVerificationEvent):
            self.handle_key_verification(event)
        elif isinstance(event, (RoomKeyRequest, RoomKeyRequestCancellation)):
            self._handle_key_requests(event)
        return decrypted_event
    def _handle_key_requests(self, event):
        if isinstance(event, RoomKeyRequest):
            if event.algorithm == Olm._megolm_algorithm:
                self.received_key_requests[event.request_id] = event
            else:
                logger.warn(
                    f"Received key request from {event.sender} via {event.requesting_device_id} "
                    f"with an unknown algorithm: {event.algorithm}"
                )
        elif isinstance(event, RoomKeyRequestCancellation):
            self.received_key_requests.pop(event.request_id, None)
            user_key = (event.sender, event.requesting_device_id)
            self.key_requests_waiting_for_session[user_key].pop(event.request_id, None)
            if not self.key_requests_waiting_for_session[user_key]:
                try:
                    device = self.device_store[event.sender][event.requesting_device_id]
                    self.key_request_devices_no_session.remove(device)
                except (KeyError, ValueError):
                    pass
            if event.request_id in self.key_request_from_untrusted:
                self.key_request_from_untrusted.pop(event.request_id)
                self.received_key_requests[event.request_id] = event
    def share_with_ourselves(self, event):
        """Share a room key with some other device owned by our own user.
        Args:
            event (RoomKeyRequest): The event of the key request.
        If the key share request is valid this will queue up a to-device
        message that holds the room key.
        Raises EncryptionError if no Olm session was found to encrypt
        the key. Raises OlmTrustError if the device that requested the key is
        not verified. Raises a KeyShareError if the request is invalid and
        can't be handled.
        """
        logger.debug(
            f"Trying to share key {event.session_id} with {event.sender}:{event.requesting_device_id}"
        )
        group_session = self.inbound_group_store.get(
            event.room_id, event.sender_key, event.session_id
        )
        if not group_session:
            raise KeyShareError(
                f"Failed to re-share key {event.session_id} with {event.sender}: No session found"
            )
        try:
            device = self.device_store[event.sender][event.requesting_device_id]
        except KeyError:
            raise KeyShareError(
                f"Failed to re-share key {event.session_id} with {event.sender}: "
                f"Unknown requesting device {event.requesting_device_id}."
            )
        session = self.session_store.get(device.curve25519)
        if not session:
            if device not in self.key_request_devices_no_session:
                self.key_request_devices_no_session.append(device)
            self.key_requests_waiting_for_session[(device.user_id, device.device_id)][
                event.request_id
            ] = event
            raise EncryptionError(
                f"No Olm session found for {device.user_id} and device {device.id}"
            )
        if not device.verified:
            raise OlmUnverifiedDeviceError(
                device,
                f"Failed to re-share key {event.session_id} with {event.sender}: "
                f"Device {event.requesting_device_id} is not verified",
            )
        logger.debug(
            f"Successfully shared a key {event.session_id} with {event.sender}:{event.requesting_device_id}"
        )
        self.outgoing_to_device_messages.append(
            self._encrypt_forwarding_key(event.room_id, group_session, session, device)
        )
    def get_active_key_requests(self, user_id, device_id):
        """Get key requests from a device that are waiting for verification.
        Args:
            user_id (str): The id of the user for which we would like to find
                the active key requests.
            device_id (str): The id of the device for which we would like to
                find the active key requests.
        """
        return [
            event
            for event in self.key_request_from_untrusted.values()
            if event.sender == user_id and event.requesting_device_id == device_id
        ]
    def continue_key_share(self, event):
        """Continue a previously interrupted key share event.
        Args:
            event (RoomKeyRequest): The event which we would like to continue.
        """
        if event not in self.key_request_from_untrusted.values():
            raise LocalProtocolError("No such pending key share request found")
        event = self.key_request_from_untrusted[event.request_id]
        if not self._collect_single_key_share(event):
            return False
        self.key_request_from_untrusted.pop(event.request_id)
        return True
    def cancel_key_share(self, event):
        """Cancel a previously interrupted key share event.
        Args:
            event (RoomKeyRequest): The event which we would like to cancel.
        """
        return bool(self.key_request_from_untrusted.pop(event.request_id, None))
    def _collect_single_key_share(self, event):
        if event.sender == self.user_id:
            try:
                self.share_with_ourselves(event)
            except KeyShareError as error:
                logger.warn(error)
            except EncryptionError as error:
                logger.warn(error)
            except OlmTrustError:
                return False
        return True
    def collect_key_requests(self):
        """Turn queued up key requests into to-device messages for key sharing.
        Returns RoomKeyRequest events that couldn't be sent out because the
        requesting device isn't verified or ignored.
        """
        events_for_users = []
        for event in self.received_key_requests.values():
            if isinstance(event, RoomKeyRequestCancellation):
                events_for_users.append(event)
                continue
            if not self._collect_single_key_share(event):
                self.key_request_from_untrusted[event.request_id] = event
                events_for_users.append(event)
        self.received_key_requests = dict()
        return events_for_users
    def _handle_key_claiming(self, response):
        keys = response.one_time_keys
        for user_id, user_devices in keys.items():
            for device_id, one_time_key in user_devices.items():
                try:
                    device = self.device_store[user_id][device_id]
                except KeyError:
                    logger.warn(
                        f"Curve key for user {user_id} and device {device_id} not found, failed to start Olm session"
                    )
                    continue
                logger.info(
                    f"Found curve key for user {user_id} and device {device_id}"
                )
                key_object = next(iter(one_time_key.values()))
                verified = self.verify_json(
                    key_object, device.ed25519, user_id, device_id
                )
                if verified:
                    logger.info(
                        f"Successfully verified signature for one-time key of device {device_id} of user {user_id}."
                    )
                    logger.info(
                        f"Creating Outbound Session for device {device_id} of user {user_id}"
                    )
                    session = self.create_session(key_object["key"], device.curve25519)
                    if device in self.wedged_devices:
                        self.wedged_devices.remove(device)
                        self._queue_dummy_message(session, device)
                    if device in self.key_request_devices_no_session:
                        self.key_request_devices_no_session.remove(device)
                        events = self.key_requests_waiting_for_session.pop(
                            (device.user_id, device.device_id), {}
                        )
                        self.received_key_requests.update(events)
                else:
                    logger.warn(
                        "Signature verification for one-time key of "
                        f"device {device_id} of user {user_id} failed, could not start "
                        "Olm session."
                    )
    def _mark_to_device_message_as_sent(self, message):
        """Mark a to-device message as sent.
        This removes the to-device message from our outgoing to-device list.
        """
        try:
            self.outgoing_to_device_messages.remove(message)
            if isinstance(message, DummyMessage):
                events = self.key_re_requests_events.pop(
                    (message.recipient, message.recipient_device), []
                )
                requested_sessions = []
                for event in events:
                    if event.session_id in requested_sessions:
                        continue
                    message = event.as_key_request(
                        event.sender, self.device_id, event.session_id, event.device_id
                    )
                    logger.info(
                        f"Queuing a room key re-request for a unwedged "
                        f"Olm session: {event.sender} {event.sender} "
                        f"{event.session_id}."
                    )
                    self.outgoing_to_device_messages.append(message)
                    requested_sessions.append(event.session_id)
            elif isinstance(message, RoomKeyRequestMessage):
                key_request = OutgoingKeyRequest.from_message(message)
                self.outgoing_key_requests[message.request_id] = key_request
                self.store.add_outgoing_key_request(key_request)
        except ValueError:
            pass
    def handle_response(self, response):
        if isinstance(response, KeysUploadResponse):
            self.account.shared = True
            self.uploaded_key_count = response.signed_curve25519_count
            self.mark_keys_as_published()
            self.save_account()
        elif isinstance(response, KeysQueryResponse):
            self._handle_key_query(response)
        elif isinstance(response, KeysClaimResponse):
            self._handle_key_claiming(response)
        elif isinstance(response, RoomKeyRequestResponse):
            key_request = OutgoingKeyRequest.from_response(response)
            self.outgoing_key_requests[response.request_id] = key_request
            self.store.add_outgoing_key_request(key_request)
        elif isinstance(response, ToDeviceResponse):
            self._mark_to_device_message_as_sent(response.to_device_message)
    def get_users_for_key_claiming(self):
        """Get the content for a key claim request that needs to be made.
        Returns a dictionary containing users as the keys and a list of devices
        for which we will claim one-time keys.
        Raises a LocalProtocolError if no key claim request needs to be made.
        """
        if not self.wedged_devices and not self.key_request_devices_no_session:
            raise LocalProtocolError("No wedged sessions found.")
        wedged = defaultdict(list)
        for device in self.wedged_devices:
            wedged[device.user_id].append(device.device_id)
        for device in self.key_request_devices_no_session:
            if device in wedged[device.user_id]:
                continue
            wedged[device.user_id].append(device.device_id)
        return wedged
    def _should_accept_forward(
        self,
        sender: str,
        sender_key: str,
        event: ForwardedRoomKeyEvent,
    ) -> bool:
        if event.algorithm != "m.megolm.v1.aes-sha2":
            logger.error(
                f"Error: unsupported forwarded room key of type {event.algorithm}"
            )
            return False
        elif event.session_id not in self.outgoing_key_requests:
            logger.info(
                "Ignoring session key we have not requested from device {}.", sender_key
            )
            return False
        key_request = self.outgoing_key_requests[event.session_id]
        if (
            event.algorithm != key_request.algorithm
            or event.room_id != key_request.room_id
            or event.session_id != key_request.session_id
        ):
            logger.info(
                "Ignoring session key with mismatched algorithm, room_id, or "
                "session id."
            )
            return False
        device = self.device_store.device_from_sender_key(event.sender, sender_key)
        if not device or not device.verified or not device.user_id == self.user_id:
            logger.warn(
                "Received a forwarded room key from a untrusted device "
                f"{event.sender}, {sender_key}"
            )
            return False
        return True
    def _handle_forwarded_room_key_event(
        self,
        sender,
        sender_key,
        payload,
    ):
        event = ForwardedRoomKeyEvent.from_dict(payload, sender, sender_key)
        if isinstance(event, (BadEvent, UnknownBadEvent)):
            return event
        if not self._should_accept_forward(sender, sender_key, event):
            return None
        content = payload["content"]
        session_sender_key = content["sender_key"]
        signing_key = content["sender_claimed_ed25519_key"]
        chain = content["forwarding_curve25519_key_chain"]
        chain.append(session_sender_key)
        session = Olm._import_group_session(
            content["session_key"],
            signing_key,
            session_sender_key,
            event.room_id,
            chain,
        )
        if not session:
            return None
        if self.inbound_group_store.add(session):
            self.save_inbound_group_session(session)
        key_request = self.outgoing_key_requests.pop(event.session_id)
        self.store.remove_outgoing_key_request(key_request)
        self.outgoing_to_device_messages.append(
            key_request.as_cancellation(self.user_id, self.device_id)
        )
        return event
    def check_if_wedged(self, event: MegolmEvent):
        """Check if a Megolm event failed decryption because they keys got lost
        because of a wedged Olm session.
        """
        try:
            device = self.device_store[event.sender][event.device_id]
        except KeyError:
            logger.warn(
                f"Received a undecryptable Megolm event from a unknown "
                f"device: {event.sender} {event.device_id}"
            )
            self.users_for_key_query.add(event.sender)
            return
        session = self.session_store.get(device.curve25519)
        if not session:
            logger.warn(
                f"Received a undecryptable Megolm event from a device "
                f"with no Olm sessions: {event.sender} {event.device_id}"
            )
            return
        session_age = datetime.now() - session.creation_time
        if (
            session_age < self._unwedging_interval
            and event.session_id not in self.outgoing_key_requests
        ):
            logger.info(
                f"Received a undecryptable Megolm event from a device "
                f"that we recently established an Olm session with: "
                f"{event.sender} {event.device_id}."
            )
            message = event.as_key_request(
                event.sender, self.device_id, event.session_id, event.device_id
            )
            self.outgoing_to_device_messages.append(message)
        if device in self.wedged_devices:
            logger.info(
                f"Received a undecryptable Megolm event from a device "
                f"that has a wedged Olm session: "
                f"{event.sender} {event.device_id}."
            )
            self.key_re_requests_events[(device.user_id, device.device_id)].append(
                event
            )
    def decrypt_event(
        self,
        event,
        room_id=None,
    ):
        logger.debug(f"Decrypting event of type {type(event).__name__}")
        if isinstance(event, OlmEvent):
            try:
                own_key = self.account.identity_keys["curve25519"]
                own_ciphertext = event.ciphertext[own_key]
            except KeyError:
                logger.warn("Olm event doesn't contain ciphertext for our key")
                return None
            if own_ciphertext["type"] == 0:
                message = OlmPreKeyMessage(own_ciphertext["body"])
            elif own_ciphertext["type"] == 1:
                message = OlmMessage(own_ciphertext["body"])
            else:
                logger.warn(f"Unsupported olm message type: {own_ciphertext['type']}")
                return None
            return self.decrypt(event.sender, event.sender_key, message)
        elif isinstance(event, MegolmEvent):
            try:
                return self.decrypt_megolm_event(event, room_id)
            except EncryptionError:
                return None
        return None
    def load(self):
        self.session_store = self.store.load_sessions()
        self.inbound_group_store = self.store.load_inbound_group_sessions()
        self.device_store = self.store.load_device_keys()
        self.outgoing_key_requests = self.store.load_outgoing_key_requests()
    async def send(
        self,
        method: str,
        path: str,
        data: Union[None, str, AsyncDataT] = None,
        headers: Optional[Dict[str, str]] = None,
        trace_context: Any = None,
        timeout: Optional[float] = None,
    ) -> ClientResponse:
        """Send a request to the homeserver.
        This function does not call receive_response().
        Args:
            method (str): The request method that should be used. One of get,
                post, put, delete.
            path (str): The URL path of the request.
            data (str, optional): Data that will be posted with the request.
            headers (Dict[str,str] , optional): Additional request headers that
                should be used with the request.
            trace_context (Any, optional): An object to use for the
                ClientSession TraceConfig context
            timeout (int, optional): How many seconds the request has before
                raising `asyncio.TimeoutError`.
                Overrides `AsyncClient.config.request_timeout` if not `None`.
        """
        assert self.client_session
        return await self.client_session.request(
            method,
            self.homeserver + path,
            data=data,
            ssl=self.ssl,
            headers=headers,
            trace_request_ctx=trace_context,
            timeout=self.config.request_timeout if timeout is None else timeout,
        )
    async def share_group_session(
        self,
        room_id: str,
        ignore_unverified_devices: bool = False,
    ) -> Union[ShareGroupSessionResponse, ShareGroupSessionError]:
        """Share a group session with a room.
        This method sends a group session to members of a room.
        Automatically called by room_send().
        Calls receive_response() to update the client state if necessary.
        Args:
            room_id(str): The room id of the room where the message should be
                sent to.
            ignore_unverified_devices(bool): Mark unverified devices as
                ignored. Ignored devices will still receive encryption
                keys for messages but they won't be marked as verified.
        Raises LocalProtocolError if the client isn't logged in, if the session
        store isn't loaded, no room with the given room id exists, the room
        isn't an encrypted room or a key sharing request is already in flight
        for this room.
        """
        assert self.olm
        try:
            room = self.rooms[room_id]
        except KeyError:
            raise LocalProtocolError(f"No such room with id {room_id}")
        if not room.encrypted:
            raise LocalProtocolError(f"Room with id {room_id} is not encrypted")
        if room_id in self.sharing_session:
            raise LocalProtocolError(f"Already sharing a group session for {room_id}")
        self.sharing_session[room_id] = AsyncioEvent()
        missing_sessions = self.get_missing_sessions(room_id)
        if missing_sessions:
            await self.keys_claim(missing_sessions)
        shared_with = set()
        try:
            requests = []
            for sharing_with, to_device_dict in self.olm.share_group_session_parallel(
                room_id,
                list(room.users.keys()),
                ignore_unverified_devices=ignore_unverified_devices,
            ):
                method, path, data = Api.to_device(
                    self.access_token, "m.room.encrypted", to_device_dict, uuid4()
                )
                requests.append(
                    self._send(
                        ShareGroupSessionResponse,
                        method,
                        path,
                        data,
                        response_data=(room_id, sharing_with),
                    )
                )
            for response in await asyncio.gather(*requests, return_exceptions=True):
                if isinstance(response, ShareGroupSessionResponse):
                    shared_with.update(response.users_shared_with)
            self.olm.outbound_group_sessions[room_id].shared = True
        except ClientConnectionError:
            raise
        finally:
            event = self.sharing_session.pop(room_id)
            event.set()
        return ShareGroupSessionResponse(room_id, shared_with)
    async def request_room_key(
        self,
        event: MegolmEvent,
        tx_id: Optional[str] = None,
    ) -> Union[RoomKeyRequestResponse, RoomKeyRequestError]:
        """Request a missing room key.
        This sends out a message to other devices requesting a room key from
        them.
        Calls receive_response() to update the client state if necessary.
        Returns either a `RoomKeyRequestResponse` if the request was successful
        or a `RoomKeyRequestError` if there was an error with the request.
        Raises a LocalProtocolError if the room key was already requested.
        Args:
            event (MegolmEvent): An undecrypted MegolmEvent for which we would
                like to request the decryption key.
        """
        uuid = tx_id or uuid4()
        if event.session_id in self.outgoing_key_requests:
            raise LocalProtocolError(
                "A key sharing request is already sent" " out for this session id."
            )
        assert self.user_id
        assert self.device_id
        message = event.as_key_request(self.user_id, self.device_id)
        method, path, data = Api.to_device(
            self.access_token, message.type, message.as_dict(), uuid
        )
        return await self._send(
            RoomKeyRequestResponse,
            method,
            path,
            data,
            (
                event.session_id,
                event.session_id,
                event.room_id,
                event.algorithm,
            ),
        )
    async def export_keys(self, outfile: str, passphrase: str, count: int = 10000):
        """Export all the Megolm decryption keys of this device.
        The keys will be encrypted using the passphrase.
        Note that this does not save other information such as the private
        identity keys of the device.
        Args:
            outfile (str): The file to write the keys to.
            passphrase (str): The encryption passphrase.
            count (int): Optional. Round count for the underlying key
                derivation. It is not recommended to specify it unless
                absolutely sure of the consequences.
        """
        assert self.store
        assert self.olm
        loop = asyncio.get_event_loop()
        inbound_group_store = self.store.load_inbound_group_sessions()
        export_keys = partial(
            self.olm.export_keys_static,
            inbound_group_store,
            outfile,
            passphrase,
            count,
        )
        await loop.run_in_executor(None, export_keys)
    async def import_keys(self, infile: str, passphrase: str):
        """Import Megolm decryption keys.
        The keys will be added to the current instance as well as written to
        database.
        Args:
            infile (str): The file containing the keys.
            passphrase (str): The decryption passphrase.
        Raises `EncryptionError` if the file is invalid or couldn't be
            decrypted.
        Raises the usual file errors if the file couldn't be opened.
        """
        assert self.store
        assert self.olm
        loop = asyncio.get_event_loop()
        import_keys = partial(self.olm.import_keys_static, infile, passphrase)
        sessions = await loop.run_in_executor(None, import_keys)
        for session in sessions:
            if self.olm.inbound_group_store.add(session):
                self.store.save_inbound_group_session(session)
    def _check_commitment(self, key: str):
        assert self.commitment
        calculated_commitment = olm.sha256(
            key + Api.to_canonical_json(self.start_verification().content)
        )
        return self.commitment == calculated_commitment
    def _send(
        self,
        request,
        request_info,
        uuid=None,
    ):
        assert self.connection
        ret_uuid, data = self.connection.send(request, uuid)
        self.requests_made[ret_uuid] = request_info
        return ret_uuid, data
    def _build_request(self, api_response, timeout=0):
        def unpack_api_call(method, *rest):
            return method, rest
        method, api_data = unpack_api_call(*api_response)
        if isinstance(self.connection, HttpConnection):
            if method == "GET":
                path = self._add_extra_path(api_data[0])
                return HttpRequest.get(self.host, path, timeout)
            elif method == "POST":
                path, data = api_data
                path = self._add_extra_path(path)
                return HttpRequest.post(self.host, path, data, timeout)
            elif method == "PUT":
                path, data = api_data
                path = self._add_extra_path(path)
                return HttpRequest.put(self.host, path, data, timeout)
        elif isinstance(self.connection, Http2Connection):
            if method == "GET":
                path = api_data[0]
                path = self._add_extra_path(path)
                return Http2Request.get(self.host, path, timeout)
            elif method == "POST":
                path, data = api_data
                path = self._add_extra_path(path)
                return Http2Request.post(self.host, path, data, timeout)
            elif method == "PUT":
                path, data = api_data
                path = self._add_extra_path(path)
                return Http2Request.put(self.host, path, data, timeout)
        assert "Invalid connection type"
    def share_group_session(
        self,
        room_id,
        ignore_missing_sessions=False,
        tx_id=None,
        ignore_unverified_devices=False,
    ):
        """Share a group session with a room.
        This method sends a group session to members of a room.
        Args:
            room_id(str): The room id of the room where the message should be
                sent to.
            tx_id(str, optional): The transaction ID of this event used to
                uniquely identify this message.
            ignore_unverified_devices(bool): Mark unverified devices as
                ignored. Ignored devices will still receive encryption
                keys for messages but they won't be marked as verified.
        Raises LocalProtocolError if the client isn't logged in, if the session
        store isn't loaded, no room with the given room id exists or the room
        isn't an encrypted room.
        """
        assert self.olm
        try:
            room = self.rooms[room_id]
        except KeyError:
            raise LocalProtocolError(f"No such room with id {room_id}")
        if not room.encrypted:
            raise LocalProtocolError(f"Room with id {room_id} is not encrypted")
        user_map, to_device_dict = self.olm.share_group_session(
            room_id,
            list(room.users.keys()),
            ignore_missing_sessions,
            ignore_unverified_devices,
        )
        uuid = tx_id or uuid4()
        request = self._build_request(
            Api.to_device(self.access_token, "m.room.encrypted", to_device_dict, uuid)
        )
        return self._send(
            request, RequestInfo(ShareGroupSessionResponse, (room_id, user_map))
        )
    def request_room_key(self, event, tx_id=None):
        """Request a missing room key.
        This sends out a message to other devices requesting a room key from
        them.
        Returns a unique uuid that identifies the request and the bytes that
        should be sent to the socket.
        Args:
            event (str): An undecrypted MegolmEvent for which we would like to
                request the decryption key.
        """
        uuid = tx_id or uuid4()
        if event.session_id in self.outgoing_key_requests:
            raise LocalProtocolError(
                "A key sharing request is already sent" " out for this session id."
            )
        assert self.user_id
        assert self.device_id
        message = event.as_key_request(self.user_id, self.device_id)
        request = self._build_request(
            Api.to_device(self.access_token, message.type, message.as_dict(), uuid)
        )
        return self._send(
            request,
            RequestInfo(
                RoomKeyRequestResponse,
                (event.session_id, event.session_id, event.room_id, event.algorithm),
            ),
        )
    def _create_response(self, request_info, transport_response, max_events=0):
        request_class = request_info.request_class
        extra_data = request_info.extra_data or ()
        try:
            content_type = str(transport_response.headers[b"content-type"], "utf-8")
        except KeyError:
            content_type = None
        try:
            disposition = str(
                transport_response.headers[b"content-disposition"], "utf-8"
            )
            filename = cgi.parse_header(disposition)[1]["filename"]
        except KeyError:
            filename = None
        is_json = content_type == "application/json"
        if issubclass(request_class, FileResponse) and is_json:
            parsed_dict = self.parse_body(transport_response)
            response = request_class.from_data(
                parsed_dict, content_type, filename, *extra_data
            )
        elif issubclass(request_class, FileResponse):
            body = transport_response.content
            response = request_class.from_data(
                body, content_type, filename, *extra_data
            )
        else:
            parsed_dict = self.parse_body(transport_response)
            if (
                transport_response.status_code == 401
                and request_class == DeleteDevicesResponse
            ):
                response = DeleteDevicesAuthResponse.from_dict(parsed_dict)
            response = request_class.from_dict(parsed_dict, *extra_data)
        assert response
        logger.info(f"Received new response of type {response.__class__.__name__}")
        response.start_time = transport_response.send_time
        response.end_time = transport_response.receive_time
        response.timeout = transport_response.timeout
        response.status_code = transport_response.status_code
        response.uuid = transport_response.uuid
        return response
    def receive(self, data):
        """Pass received data to the client"""
        assert self.connection
        try:
            response = self.connection.receive(data)
        except (h11.RemoteProtocolError, h2.exceptions.ProtocolError) as e:
            raise RemoteTransportError(e)
        if response:
            try:
                request_info = self.requests_made.pop(response.uuid)
            except KeyError:
                logger.error(f"{pprint.pformat(self.requests_made)}")
                raise
            if response.is_ok:
                logger.info(f"Received response of type: {request_info.request_class}")
            else:
                logger.info(
                    ("Error with response of type type: {}, " "error code {}").format(
                        request_info.request_class, response.status_code
                    )
                )
            self.parse_queue.append((request_info, response))
        return
    def olm_account_shared(self) -> bool:
        """Check if the clients Olm account is shared with the server.
        Returns True if the Olm account is shared, False otherwise.
        """
        assert self.olm
        return self.olm.account.shared
    def invalidate_outbound_session(self, room_id: str):
        """Explicitly remove encryption keys for a room.
        Args:
            room_id (str): Room id for the room the encryption keys should be
                removed.
        """
        assert self.olm
        session = self.olm.outbound_group_sessions.pop(room_id, None)
        if session and not session.shared:
            self.olm.outbound_group_sessions[room_id] = session
        elif session:
            logger.info(f"Invalidating session for {room_id}")
    def _invalidate_outbound_sessions(self, device):
        assert self.olm
        for room in self.rooms.values():
            if device.user_id in room.users:
                self.invalidate_outbound_session(room.room_id)
    def verify_device(self, device: OlmDevice) -> bool:
        """Mark a device as verified.
        A device needs to be either trusted/ignored or blacklisted to either
        share room encryption keys with it or not.
        This method adds the device to the trusted devices and enables sharing
        room encryption keys with it.
        Args:
            device (OlmDevice): The device which should be added to the trust
                list.
        Returns true if the device was verified, false if it was already
        verified.
        """
        assert self.olm
        changed = self.olm.verify_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def unverify_device(self, device: OlmDevice) -> bool:
        """Unmark a device as verified.
        This method removes the device from the trusted devices and disables
        sharing room encryption keys with it. It also invalidates any
        encryption keys for rooms that the device takes part of.
        Args:
            device (OlmDevice): The device which should be added to the trust
                list.
        Returns true if the device was unverified, false if it was already
        unverified.
        """
        assert self.olm
        changed = self.olm.unverify_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def blacklist_device(self, device: OlmDevice) -> bool:
        """Mark a device as blacklisted.
        Devices on the blacklist will not receive room encryption keys and
        therefore won't be able to decrypt messages coming from this client.
        Args:
            device (OlmDevice): The device which should be added to the
                blacklist.
        Returns true if the device was added, false if it was on the blacklist
        already.
        """
        assert self.olm
        changed = self.olm.blacklist_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def unblacklist_device(self, device: OlmDevice) -> bool:
        """Unmark a device as blacklisted.
        Args:
            device (OlmDevice): The device which should be removed from the
                blacklist.
        Returns true if the device was removed, false if it wasn't on the
        blacklist and no removal happened.
        """
        assert self.olm
        changed = self.olm.unblacklist_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def ignore_device(self, device: OlmDevice) -> bool:
        """Mark a device as ignored.
        Ignored devices will still receive room encryption keys, despire not
        being verified.
        Args:
            device (OlmDevice): the device to ignore
        Returns true if device is ignored, or false if it is already on the
        list of ignored devices.
        """
        assert self.olm
        changed = self.olm.ignore_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def unignore_device(self, device: OlmDevice) -> bool:
        """Unmark a device as ignored.
        Args:
            device (OlmDevice): The device which should be removed from the
                list of ignored devices.
        Returns true if the device was removed, false if it wasn't on the
        list and no removal happened.
        """
        assert self.olm
        changed = self.olm.unignore_device(device)
        if changed:
            self._invalidate_outbound_sessions(device)
        return changed
    def receive_response(
        self, response: Response
    ) -> Union[None, Coroutine[Any, Any, None]]:
        """Receive a Matrix Response and change the client state accordingly.
        Some responses will get edited for the callers convenience e.g. sync
        responses that contain encrypted messages. The encrypted messages will
        be replaced by decrypted ones if decryption is possible.
        Args:
            response (Response): the response that we wish the client to handle
        """
        if not isinstance(response, Response):
            raise ValueError("Invalid response received")
        if isinstance(response, LoginResponse):
            self._handle_login(response)
        elif isinstance(response, LogoutResponse):
            self._handle_logout(response)
        elif isinstance(response, RegisterResponse):
            self._handle_register(response)
        elif isinstance(response, SyncResponse):
            self._handle_sync(response)
        elif isinstance(response, RoomMessagesResponse):
            self._handle_messages_response(response)
        elif isinstance(response, RoomContextResponse):
            self._handle_context_response(response)
        elif isinstance(response, KeysUploadResponse):
            self._handle_olm_response(response)
        elif isinstance(response, KeysQueryResponse):
            self._handle_olm_response(response)
        elif isinstance(response, KeysClaimResponse):
            self._handle_olm_response(response)
        elif isinstance(response, ShareGroupSessionResponse):
            self._handle_olm_response(response)
        elif isinstance(response, JoinedMembersResponse):
            self._handle_joined_members(response)
        elif isinstance(response, RoomKeyRequestResponse):
            self._handle_olm_response(response)
        elif isinstance(response, RoomForgetResponse):
            self._handle_room_forget_response(response)
        elif isinstance(response, ToDeviceResponse):
            self._handle_olm_response(response)
        elif isinstance(response, RoomGetEventResponse):
            if isinstance(response.event, MegolmEvent) and self.olm is not None:
                try:
                    response.event = self.decrypt_event(response.event)
                except EncryptionError:
                    pass
        elif isinstance(response, PresenceGetResponse):
            self._handle_presence_response(response)
        elif isinstance(response, ErrorResponse):
            if response.soft_logout:
                self.access_token = ""
        return None
    def get_users_for_key_claiming(self) -> Dict[str, List[str]]:
        """Get the content for a key claim request that needs to be made.
        Returns a dictionary containing users as the keys and a list of devices
        for which we will claim one-time keys.
        Raises a LocalProtocolError if no key claim request needs to be made.
        """
        assert self.olm
        return self.olm.get_users_for_key_claiming()
    def get_active_key_requests(
        self, user_id: str, device_id: str
    ) -> List[RoomKeyRequest]:
        """Get key requests from a device that are waiting for verification.
        Args:
            user_id (str): The id of the user for which we would like to find
                the active key requests.
            device_id (str): The id of the device for which we would like to
                find the active key requests.
        Example:
            >>>
            >>>
            >>>
            >>>
            >>>   def key_share_cb(event):
            ...       user_id = event.sender
            ...       device_id = event.requesting_device_id
            ...       device = client.device_store[user_id][device_id]
            ...       client.verify_device(device)
            ...       for request in client.get_active_key_requests(
            ...           user_id, device_id):
            ...           client.continue_key_share(request)
            >>>   client.add_to_device_callback(key_share_cb)
        Returns:
            list: A list of actively waiting key requests from the given user.
        """
        assert self.olm
        return self.olm.get_active_key_requests(user_id, device_id)
    def continue_key_share(self, event: RoomKeyRequest) -> bool:
        """Continue a previously interrupted key share event.
        To handle room key requests properly client users need to add a
        callback for RoomKeyRequest:
            >>> client.add_to_device_callback(callback, RoomKeyRequest)
        This callback will be run only if a room key request needs user
        interaction, that is if a room key request is coming from an untrusted
        device.
        After a user has verified the requesting device the key sharing can be
        continued using this method:
            >>> client.continue_key_share(room_key_request)
        Args:
            event (RoomKeyRequest): The event which we would like to continue.
        If the key share event is continued successfully a to-device message
        will be queued up in the `client.outgoing_to_device_messages` list
        waiting to be sent out
        Returns:
            bool: True if the request was continued, False otherwise.
        """
        assert self.olm
        return self.olm.continue_key_share(event)
    def cancel_key_share(self, event: RoomKeyRequest) -> bool:
        """Cancel a previously interrupted key share event.
        This method is the counterpart to the `continue_key_share()` method. If
        a user choses not to verify a device and does not want to share room
        keys with such a device it should cancel the request with this method.
            >>> client.cancel_key_share(room_key_request)
        Args:
            event (RoomKeyRequest): The event which we would like to cancel.
        Returns:
            bool: True if the request was cancelled, False otherwise.
        """
        assert self.olm
        return self.olm.cancel_key_share(event)
    def send(self, request, uuid=None):
        data = b""
        if not isinstance(request, HttpRequest):
            raise TypeError("Invalid request type for HttpConnection")
        if self._connection.our_state == h11.IDLE and not self._current_response:
            data = data + self._connection.send(request._request)
            if request._data:
                data = data + self._connection.send(request._data)
            data = data + self._connection.send(request._end_of_message)
            if request.response:
                self._current_response = request.response
            else:
                self._current_response = HttpResponse(uuid, request.timeout)
            assert self._current_response
            self._current_response.mark_as_sent()
            return self._current_response.uuid, data
        else:
            request.response = HttpResponse(uuid, request.timeout)
            self._message_queue.append(request)
            return request.response.uuid, b""

def _create_pg_connection(config):
    if 'server' in config:
        username = '@'.join([config['username'], config['server']])
    else:
        username = config['username']
    return psycopg2.connect(
        database=config['database'],
        user=username,
        host=config['host'],
        port=config['port'],
        password=config['password'],
    )
def check_db_or_user_exists(db_name, db_user, config):
    with _create_pg_connection(config) as con:
        with con.cursor() as cur:
            cur.execute("SELECT 1 FROM pg_database WHERE datname='{}';".format(db_name))
            db_exists = cur.fetchone() is not None
            cur.execute("SELECT 1 FROM pg_roles WHERE rolname='{}';".format(db_user))
            user = cur.fetchone()
            user_exists = user is not None
            return db_exists or user_exists
def create_postgres_db(connection_dict, config):
    if check_db_or_user_exists(connection_dict["db_name"], connection_dict["db_username"], config):
        raise ValueError("db or user already exists")
    with _create_pg_connection(config) as con:
        con.set_isolation_level(ISOLATION_LEVEL_AUTOCOMMIT)
        with con.cursor() as cur:
            create_role = "CREATE USER {db_username} WITH PASSWORD '{db_pwd}';".format(**connection_dict)
            drop_role = "DROP ROLE {db_username};".format(**connection_dict)
            grant_role = 'GRANT {db_username} TO "{postgraas_user}";'.format(
                db_username=connection_dict['db_username'], postgraas_user=get_normalized_username(config['username'])
            )
            create_database = "CREATE DATABASE {db_name} OWNER {db_username};".format(**connection_dict)
            try:
                cur.execute(create_role)
                cur.execute(grant_role)
            except psycopg2.ProgrammingError as e:
                raise ValueError(e.args[0])
            try:
                cur.execute(create_database)
            except psycopg2.ProgrammingError as e:
                cur.execute(drop_role)
                raise ValueError(e.args[0])
def get_normalized_username(username):
    return username.split('@')[0]
def delete_database(db_name, config):
    with _create_pg_connection(config) as con:
        con.set_isolation_level(ISOLATION_LEVEL_AUTOCOMMIT)
        with con.cursor() as cur:
            try:
                cur.execute('''DROP DATABASE "{}";'''.format(db_name))
            except psycopg2.ProgrammingError as e:
                raise ValueError(e.args[0])
def delete_user(username, config):
    with _create_pg_connection(config) as con:
        con.set_isolation_level(ISOLATION_LEVEL_AUTOCOMMIT)
        with con.cursor() as cur:
            try:
                cur.execute('''DROP USER "{}";'''.format(get_normalized_username(username)))
            except psycopg2.ProgrammingError as e:
                raise ValueError(e.args[0])

