            self._log.debug(f'VULN: {json.dumps(vuln)}')
            self._log.debug(f'ISSUE: {json.dumps(issue)}')
            self._log.debug(f'SUB-ISSUE: {json.dumps(subissue)}')
            return
        try:
            i = self._jira.issues.upsert(fields=issue, jql=' and '.join(jql))
